{"command":"cd /workspace && rm -f 'work/pv$V.xm' && for V in 64 8 16 32 65 80 100; do ft2 call pattern_clear '{"pattern":0}' >/dev/null; ft2 call pattern_set_cell "{\"pattern\":0,\"row\":0,\"channel\":0,\"note\":\"A-4\",\"instrument\":1,\"volume\":$V}" >/dev/null; ft2 call module_save "{\"path\":\"work/pvv$V.xm\",\"format\":\"xm}" >/dev/null; done; python3 - <<'EOF'
import struct, os
def volbyte(fn):
    d=open(fn,'rb').read()
    off=17+20+1+20+2
    hsize,=struct.unpack_from('<I',d,off)
    o=off+hsize
    plen,=struct.unpack_from('<I',d,o); rows,=struct.unpack_from('<H',d,o+5); dsize,=struct.unpack_from('<H',d,o+7)
    pd=d[o+plen:o+plen+dsize]
    if not pd: return ("empty",)
    b=pd[0]; i=1; out=[b]
    for bit,name in ((1,'note'),(2,'ins'),(4,'vol'),(8,'fx'),(16,'par')):
        if b&bit: out.append((name,pd[i])); i+=1
    return tuple(out)
for v in (24,64,8,16,32,65,80,100):
    fn=f'work/pvv{v}.xm'
    print(v, volbyte(fn) if os.path.exists(fn) else "missing")
EOF"}

