{"command":"cd /workspace && cat > work/ft2drv.py <<'EOF'
import subprocess, json, sys

def call(name, **args):
    r = subprocess.run(['ft2','call',name,json.dumps(args)], capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(f"{name} {args} failed: {r.stdout} {r.stderr}")
    return r.stdout.strip()

def batch(calls, quiet=True):
    with open('work/batch.json','w') as f:
        json.dump([{"name":n,"arguments":a} for n,a in calls], f)
    r = subprocess.run(['ft2','batch','work/batch.json'], capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(f"batch failed: {r.stdout[-3000:]} {r.stderr[-3000:]}")
    out = r.stdout
    errs = [l for l in out.splitlines() if 'isError": true' in l or '"isError":true' in l]
    if errs:
        raise RuntimeError(f"batch had errors: {errs[:5]} (total {len(errs)})")
    return out
EOF
